<script lang="ts">
	import '../app.css';
	import { supabase } from '$lib/supabaseClient';
	import { onMount } from 'svelte';
	import { writable } from 'svelte/store';
	import { SvelteURLSearchParams } from 'svelte/reactivity';
	import { page } from '$app/stores';
	import { resolve } from '$app/paths';
	import { APP_VERSION } from '$lib/version';
	import type { Snippet } from 'svelte';

	let { children }: { children: Snippet } = $props();

	type Session = Awaited<ReturnType<typeof supabase.auth.getSession>>['data']['session'];
	const session = writable<Session | null>(null);
	let authChecked = $state(false);

	// #{#ath1a} Public routes that do not require authentication
	const publicRoutes = ['/', '/login', '/forgot-password', '/reset-password'];

	let isPublicRoute = $derived(publicRoutes.includes($page.url.pathname));

	onMount(() => {
		// Subscribe synchronously so onMount can return a synchronous cleanup
		// (an async onMount callback can't return a teardown function).
		const { data: sub } = supabase.auth.onAuthStateChange((_e, s) => session.set(s));

		void (async () => {
			const { data } = await supabase.auth.getSession();
			session.set(data.session);
			authChecked = true;
		})();

		return () => {
			sub.subscription.unsubscribe();
		};
	});

	async function logout() {
		await supabase.auth.signOut();
		window.location.href = '/login';
	}

	// #{#sdf3a} Preserve date filter query parameters in navigation.
	// `resolve()` only accepts a single concrete route literal, so each nav link
	// branches `resolve(`/route?${filterQuery}`)` vs `resolve('/route')` (see the
	// same pattern in expenses/+page.svelte). This derived is just the query body
	// (no leading `?`), shared by every link.
	let filterQuery = $derived.by(() => {
		const params = $page.url.searchParams;
		const dateFrom = params.get('dateFrom');
		const dateTo = params.get('dateTo');

		const newParams = new SvelteURLSearchParams();
		if (dateFrom) newParams.set('dateFrom', dateFrom);
		if (dateTo) newParams.set('dateTo', dateTo);

		return newParams.toString();
	});
</script>

