	const config = readConfig();
	const admin = createAdminClient(config);
	console.log(`\nDemo teardown → target: ${targetHost(config.url)}\n`);

	const result = await teardownDemo(admin);
	console.log(
		`✓ Removed ${result.usersDeleted} demo user(s), ${result.familiesDeleted} family(ies).\n`
	);
}

main().catch((err) => {
	console.error(`\n✗ Demo teardown failed: ${err instanceof Error ? err.message : err}\n`);
	process.exit(1);
});

