/**
 * Shared config + teardown for the demo-data seed.
 *
 * The demo seed populates a self-contained "Sample Family (DEMO)" — two auth
 * users, a family, categories/hierarchy, receipts and transactions — so the
 * running app can be logged into for documentation screenshots/videos and
 * manual testing. See docs/demo-seed.md.
 *
 * Everything here is keyed off the two demo emails and the demo family name, so
 * teardown can only ever touch demo artifacts, never real data. All access uses
 * the service-role key (bypasses RLS) against the *remote* project.
 */
import { createClient, type SupabaseClient } from '@supabase/supabase-js';

// ---- Identifiers (the only things that mark a row as "demo") ----------------

export const FAMILY_NAME = 'Sample Family (DEMO)';
export const OWNER_EMAIL = 'sample.parent@example.com';
export const MEMBER_EMAIL = 'sample.partner@example.com';
export const DEMO_EMAILS = [OWNER_EMAIL, MEMBER_EMAIL];

// ---- Environment / client ---------------------------------------------------

export type DemoConfig = { url: string; serviceRoleKey: string };

/**
 * Read + validate the required environment. Hard-fails with a clear message
 * rather than half-running against the wrong target.
 */
export function readConfig(): DemoConfig {
	const url = process.env.PUBLIC_SUPABASE_URL;
	const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

	const missing: string[] = [];
	if (!url) missing.push('PUBLIC_SUPABASE_URL');
	if (!serviceRoleKey) missing.push('SUPABASE_SERVICE_ROLE_KEY');
	if (missing.length > 0) {
		throw new Error(
			`Missing required env var(s): ${missing.join(', ')}.\n` +
				'Run via 1Password, e.g.:  op run --env-file=.env -- npm run seed:demo'
		);
	}

	return { url: url!, serviceRoleKey: serviceRoleKey! };
}

export function createAdminClient(config: DemoConfig): SupabaseClient {
	return createClient(config.url, config.serviceRoleKey, {
		auth: { autoRefreshToken: false, persistSession: false }
	});
}

/** Echo the target host so an accidental run against the wrong project is visible. */
export function targetHost(url: string): string {
	try {
		return new URL(url).host;
	} catch {
		return url;
	}
}

// ---- Teardown ---------------------------------------------------------------

export type TeardownSummary = { usersDeleted: number; familiesDeleted: number };

/** Find the demo auth users by email (paginates the admin user list). */
async function findDemoUserIds(admin: SupabaseClient): Promise<string[]> {
	const ids: string[] = [];
	const perPage = 1000;
	for (let page = 1; ; page++) {
		const { data, error } = await admin.auth.admin.listUsers({ page, perPage });
		if (error) throw new Error(`listUsers failed: ${error.message}`);
		for (const user of data.users) {
			if (user.email && DEMO_EMAILS.includes(user.email)) ids.push(user.id);
		}
		if (data.users.length < perPage) break;
	}
	return ids;
}

/**
 * Delete every demo artifact. Scoped strictly to the demo emails and the demo
 * family name, so it cannot touch real data.
 *
 * Deleting the auth users cascades their receipts + expense_categories +
 * family memberships. Deleting the family cascades its transactions, categories,
 * category_groups and importance_areas. Doing both leaves nothing behind.
 */
export async function teardownDemo(admin: SupabaseClient): Promise<TeardownSummary> {
	const userIds = await findDemoUserIds(admin);
	for (const id of userIds) {
		const { error } = await admin.auth.admin.deleteUser(id);
		if (error) throw new Error(`deleteUser(${id}) failed: ${error.message}`);
	}

	const { data: families, error: famErr } = await admin
		.from('families')
		.delete()
		.eq('name', FAMILY_NAME)
		.select('id');
	if (famErr) throw new Error(`delete families failed: ${famErr.message}`);

	return { usersDeleted: userIds.length, familiesDeleted: families?.length ?? 0 };
}

