/** Loopback hosts the demo seed is allowed to touch. */
const LOCAL_HOSTS = ['127.0.0.1', 'localhost', '[::1]', '::1'];

/**
 * Read + validate the required environment. Hard-fails with a clear message
 * rather than half-running against the wrong target.
 */
export function readConfig(): DemoConfig {
	const url = process.env.PUBLIC_SUPABASE_URL;
	const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

	const missing: string[] = [];
	if (!url) missing.push('PUBLIC_SUPABASE_URL');
	if (!serviceRoleKey) missing.push('SUPABASE_SERVICE_ROLE_KEY');
	if (missing.length > 0) {
		throw new Error(
			`Missing required env var(s): ${missing.join(', ')}.\n` +
				'The demo scripts inject these themselves — run:  npm run seed:demo'
		);
	}

	// The demo password is a checked-in constant, so "don't seed production" has
	// to be an impossibility rather than a convention. Refuse anything that is
	// not the local stack, and fail *before* the service-role client is built.
	const host = new URL(url!).hostname;
	if (!LOCAL_HOSTS.includes(host)) {
		throw new Error(
			`Refusing to run against a non-local target: ${host}.\n` +
				'Demo data is local-only — the demo users share a fixed, checked-in password,\n' +
				'so seeding a remote project would plant a known credential in it.\n' +
				'Start the local stack with `npm run db:up` and re-run.'
		);
	}

	return { url: url!, serviceRoleKey: serviceRoleKey! };
}

